def compute(vars):
    total_restricted_units = vars["v2"]
    restricted_units_vesting_2011 = vars["v1"]

    if total_restricted_units == 0:
        return None

    portion = restricted_units_vesting_2011 / total_restricted_units

    return {
        "value": portion,
        "trace": {
            "restricted_units_vesting_2011": restricted_units_vesting_2011,
            "total_restricted_units": total_restricted_units,
            "portion": portion,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "proportion"
            }
        }
    }
